import { startServer } from '../src/server';
import http from 'http';
import fs from 'fs';
import path from 'path';
import os from 'os';
import net from 'net';

function get(
  port: number,
  urlPath: string
): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    http.get(`http://localhost:${port}${urlPath}`, (res) => {
      let body = '';
      res.on('data', (chunk: Buffer) => (body += chunk.toString()));
      res.on('end', () =>
        resolve({ status: res.statusCode || 0, body })
      );
    }).on('error', reject);
  });
}

function rawGet(
  port: number,
  rawPath: string
): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const socket = new net.Socket();
    socket.connect(port, 'localhost', () => {
      socket.write(
        `GET ${rawPath} HTTP/1.1\r\nHost: localhost:${port}\r\nConnection: close\r\n\r\n`
      );
    });
    let data = '';
    socket.on('data', (chunk: Buffer) => {
      data += chunk.toString();
    });
    socket.on('end', () => {
      const statusMatch = data.match(/HTTP\/1\.1 (\d+)/);
      const status = statusMatch ? parseInt(statusMatch[1], 10) : 0;
      const bodyStart = data.indexOf('\r\n\r\n');
      const body = bodyStart >= 0 ? data.slice(bodyStart + 4) : '';
      resolve({ status, body });
    });
    socket.on('error', reject);
  });
}

async function waitForServer(port: number, retries = 30): Promise<void> {
  for (let i = 0; i < retries; i++) {
    try {
      await get(port, '/');
      return;
    } catch {
      await new Promise((r) => setTimeout(r, 100));
    }
  }
  throw new Error('Server did not start');
}

describe('startServer', () => {
  let outputDir: string;
  let contentDir: string;
  let templateDir: string;
  let port: number;
  let serverInstance: {
    server: http.Server;
    close: () => Promise<void>;
    rebuild: () => void;
  };

