```typescript
import fs from 'fs';
import path from 'path';
import crypto from 'crypto';

export interface CachedPage {
  page: Page;
  html: string;
}

export interface CacheManifest {
  contentHashes: Record<string, string>; // relPath -> sha256
  templateHash: string;                  // combined sha256 of all template files
  pages: Record<string, CachedPage>;     // slug -> {page, html}
  indexHtml?: string;
}

export class BuildCache {
  private data: CacheManifest | null = null;
  private cachePath: string;

  constructor(cachePath: string) {
    this.cachePath = cachePath;
  }

  static computeHash(content: string): string {
    return crypto.createHash('sha256').update(content).digest('hex');
  }

  static computeFileHash(filePath: string): string {
    const content = fs.readFileSync(filePath, 'utf-8');
    return this.computeHash(content);
  }

  static computeTemplateHash(templateDir: string): string {
    if (!fs.existsSync(templateDir)) return '';

    const hashes: string[] = [];
    const walkDir = (dir: string) => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          walkDir(fullPath);
        } else if (entry.name.endsWith('.hbs')) {
          hashes.push(BuildCache.computeFileHash(fullPath));
        }
      }
    };
    walkDir(templateDir);

    return this.computeHash(hashes.join(''));
  }

  load(): boolean {
    try {
      if (fs.existsSync(this.cachePath)) {
        this.data = JSON.parse(fs.readFileSync(this.cachePath, 'utf-8'));
        return true;
      }
    } catch {
      // invalid cache, ignore
    }
    return false;
  }

  save(): void {
    if (this.data) {
      fs.writeFileSync(this.cachePath, JSON.stringify(this.data, null, 2));
    }
  }

  clear(): void {
    this.data = {
      contentHashes: {},
      templateHash: '',
      pages: {},
    };
    try {
      if (fs.existsSync(this.cachePath)) {
        fs.unlinkSync(this.cachePath);
      }
    } catch {
      // ignore
    }
  }

  isPopulated(): boolean {
    return this.data !== null;
  }

  getContentHash(relPath: string): string | undefined {
    return this.data?.contentHashes[relPath];
  }

  setContentHash(relPath: string, hash: string): void {
    if (this.data) {
      this.data.contentHashes[relPath] = hash;
    }
  }

  getTemplateHash(): string {
    return this.data?.templateHash || '';
  }

  setTemplateHash(hash: string): void {
    if (this.data) {
      this.data.templateHash = hash;
    }
  }

  getCachedPage(slug: string): CachedPage | undefined {
    return this.data?.pages[slug];
  }

  setCachedPage(slug: string, cachedPage: CachedPage): void {
    if (this.data) {
      this.data.pages[slug] = cachedPage;
    }
  }

  getIndexHtml(): string | undefined {
    return this.data?.indexHtml;
  }

  setIndexHtml(html: string): void {
    if (this.data) {
      this.data.indexHtml = html;
    }
  }
}
```

