export function parseDirectory(
  contentDir: string,
  cache?: BuildCache,
  stats?: ParseStats
): Page[] {
  if (!fs.existsSync(contentDir)) {
    if (cache && cache.isPopulated()) {
      for (const key of Object.keys(cache.getCachedSlugs())) {
        cache.removeCachedPage(key);
